/**
 * Scrum of Scrums — tool-local actions.
 *
 * Category: Ceremonies (squad S3 — cross-team coordination)
 * Tool:     Per-meeting log of blockers / dependencies / decisions / updates
 *
 * Agent surface: tool.scrum_of_scrums.*
 * Backing CRUD : workspace.sos_entry.* (auto-generated by defineCrudActions
 *                in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern ────────────────────────────────────────
 * SosEntry is a record-keeping entity: generic create / list / update /
 * delete already exist via the workspace.sos_entry.* surface. This file
 * adds the verbs an agent reaches for in the Scrum-of-Scrums domain:
 *
 *   1. list_state    — all entries + a summary (byKind, byStatus, and the
 *                      stale OPEN blockers ≥3 days old) so an agent can
 *                      answer "what's blocking which team?" in one call.
 *   2. mark_resolved — close out a blocker/dependency and stamp resolvedAt.
 *                      Idempotent — re-resolving a resolved entry is a no-op.
 *
 * ─── ENTITY KIND ─────────────────────────────────────────────────────
 * Entity kind is "workspace:sosEntry" (camelCase via kindFromToolId),
 * matching the browser sync engine's registerCollection("sosEntry", …) so
 * MCP-written entries round-trip into the browser store.
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { SosEntry } from "@/lib/stores/workspace-types";
import { todayLocalISO } from "@/lib/utils/formatters";

/** Server-side entity kind. Matches kindFromToolId("workspace.sos_entry")
 *  used by the auto-generated CRUD, and the browser sync engine's
 *  "workspace:sosEntry" collection — both camelCase, so reads/writes here
 *  line up with the generic surface and round-trip to the browser. */
const KIND_SOS = "workspace:sosEntry";

const ws = () => useWorkspaceStore.getState();

/** Whole-day age of an entry from its meetingDate, anchored on LOCAL
 *  midnight like the board's ageDays (BUG-T7-scrum-of-scrums-1). A UTC diff
 *  aged entries a day early in the evening west of UTC, so the agent's
 *  staleBlockers disagreed with the board's "aged ≥3 days" callout.
 *  Returns null on a malformed date so callers skip it rather than bucket
 *  a NaN into the stale-blocker filter. */
function ageDays(e: SosEntry): number | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(e.meetingDate ?? "");
  if (!m) return null;
  const meeting = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  // Round, not floor: across a DST change two local midnights are 23 or 25 h
  // apart per day, and flooring 71 h aged a 3-day-old blocker as 2.
  return Math.max(0, Math.round((today - meeting) / 86_400_000));
}

/** Build the {total, byKind, byStatus, staleBlockers, items} response.
 *  Shared by the browser and MCP paths so both return an identical shape —
 *  drift would mean an agent gets different shapes from chat vs MCP. */
function summarize(items: SosEntry[]) {
  const byKind: Record<SosEntry["kind"], number> = {
    blocker: 0,
    dependency: 0,
    decision: 0,
    update: 0,
  };
  const byStatus: Record<SosEntry["status"], number> = { open: 0, resolved: 0 };
  const staleBlockers: SosEntry[] = [];
  for (const e of items) {
    if (e.kind in byKind) byKind[e.kind] += 1;
    if (e.status in byStatus) byStatus[e.status] += 1;
    if (e.kind === "blocker" && e.status === "open") {
      const age = ageDays(e);
      if (age !== null && age >= 3) staleBlockers.push(e);
    }
  }
  return { total: items.length, byKind, byStatus, staleBlockers, items };
}

// ──────── tool.scrum_of_scrums.list_state ────────
// The agent's opening question for a coordination log is "what's the
// state across teams?" — returning the items plus byKind/byStatus and the
// aged-open-blocker list in one round-trip avoids follow-up reduces.
registry.register({
  id: "tool.scrum_of_scrums.list_state",
  toolId: "tool.scrum_of_scrums",
  name: "list_state",
  category: "read",
  description:
    "List all Scrum of Scrums entries with a summary. Returns {total, byKind: {blocker, dependency, decision, update}, byStatus: {open, resolved}, staleBlockers: SosEntry[] (open blockers ≥3 days old), items: SosEntry[]}.",
  paramsSchema: z.object({}),
  handler: async () => summarize(ws().sosEntries ?? []),
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<SosEntry>(ctx.userId, KIND_SOS);
    return summarize(items);
  },
});

// ──────── tool.scrum_of_scrums.mark_resolved ────────
// Convenience over workspace.sos_entry.update — resolving is the single
// most-common lifecycle transition for a blocker/dependency, and the
// agent shouldn't marshal a full {patch: {status, resolvedAt}} object.
// requiresConfirmation:false — closing an entry isn't destructive (the
// row is retained, just flagged resolved).
registry.register({
  id: "tool.scrum_of_scrums.mark_resolved",
  toolId: "tool.scrum_of_scrums",
  name: "mark_resolved",
  category: "write",
  requiresConfirmation: false,
  description:
    "Mark a Scrum of Scrums entry resolved and stamp resolvedAt (defaults to today, YYYY-MM-DD). Idempotent — a no-op if already resolved. Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    resolvedAt: z.string().optional(),
  }),
  handler: async (params) => {
    const current = (ws().sosEntries ?? []).find((e) => e.id === params.id);
    if (!current) return { updated: false };
    if (current.status === "resolved") return { updated: true };
    ws().upsertSosEntry({
      ...current,
      status: "resolved",
      resolvedAt: params.resolvedAt ?? todayLocalISO(),
    });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<SosEntry>(ctx.userId, KIND_SOS, params.id);
    if (!current) return { updated: false };
    if (current.status === "resolved") return { updated: true };
    await serverUpsertEntity<SosEntry>(ctx.userId, KIND_SOS, {
      ...current,
      status: "resolved",
      resolvedAt: params.resolvedAt ?? todayLocalISO(),
    });
    return { updated: true };
  },
});
